diff --git a/test.js b/test.js
index e303a46..3f3852a 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,42 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue leaves the active promise untouched and drops every queued function', async t => {
+	const limit = pLimit(1);
+	let queuedRunCount = 0;
+
+	const runningPromise = limit(async () => {
+		await delay(50);
+		return 'active';
+	});
+
+	const pendingPromises = Array.from({length: 3}, () => limit(async () => {
+		queuedRunCount++;
+		await delay(10);
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	t.is(limit.clearQueue(), undefined);
+
+	// The running function keeps its slot; only the queue is emptied.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+	t.is(await runningPromise, 'active');
+
+	// Cleared functions are never invoked and their promises stay pending by default.
+	const sentinel = Symbol('pending');
+	t.is(await Promise.race([...pendingPromises, delay(50, sentinel)]), sentinel);
+	t.is(queuedRunCount, 0);
+
+	// The public API is unchanged, so the limit still accepts new work.
+	t.is(limit.activeCount, 0);
+	t.is(await limit(() => 'after clear'), 'after clear');
+	t.is(limit.concurrency, 1);
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;
